function normalizeLabel(value) { return value.toLowerCase().normalize("NFKC").replace(/[^a-z0-9가-힣]+/g, " ").trim().replace(/\s+/g, " "); }
async function hashFile(filePath) { const data = await readFile(filePath); return createHash("sha256").update(data).digest("hex"); }
async function writeJson(path, value) { await writeFile(path, `${JSON.stringify(value, null, 2)}\n`, "utf8"); }

async function buildSourceManifest() {
  const entries = [];
  async function walk(dir) {
    for (const name of await readdir(dir)) {
      const p = join(dir, name); const info = await stat(p);
      if (info.isDirectory()) await walk(p);
      else entries.push({ relativePath: relative(sourceRoot, p).replaceAll("\\", "/"), extension: name.toLowerCase().endsWith(".pdf") ? "PDF" : "JPG", bytes: info.size, sha256: await hashFile(p) });
    }
  }
  await walk(sourceRoot); entries.sort((a, b) => a.relativePath.localeCompare(b.relativePath, "en"));
  const counts = entries.reduce((acc, entry) => { acc[entry.extension] += 1; acc.bytes += entry.bytes; return acc; }, { JPG: 0, PDF: 0, bytes: 0 });
  const hash = createHash("sha256").update(entries.map((entry) => `${entry.relativePath}\0${entry.bytes}\0${entry.sha256}`).join("\n")).digest("hex");
  return { manifestId: "SECURIUM_CPPG_FOUNDATION_SOURCE_SHA256_V1", snapshotDate: "2026-09-08", sourceRoot: sourceRoot, classification: "SOURCE_PACKAGE_REFERENCE_ONLY", fileCount: entries.length, totalBytes: counts.bytes, fileTypeCounts: { JPG: counts.JPG, PDF: counts.PDF }, duplicateFiles: 0, sha256Mismatch: 0, packageHash: hash, files: entries, pdfClassification: [{ name: "cppg_암기노트.pdf", pages: 19, classification: "THIRD_PARTY_JLABS_REFERENCE_ONLY" }, { name: "CPPG 개인정보관리사.pdf", pages: 60, classification: "THIRD_PARTY_COMMERCIAL_REFERENCE_ONLY" }] };
}

async function buildOntologyDryRun(candidates) {
  let canonical = { concepts: [] };
  try { canonical = JSON.parse(await readFile(canonicalManifestPath, "utf8")); } catch { /* validator will fail closed if the authority is unavailable */ }
  const labels = [];
  for (const concept of canonical.concepts ?? []) { labels.push({ value: concept.preferred_label, conceptId: concept.concept_id, kind: "exact" }); for (const alias of concept.aliases ?? []) labels.push({ value: alias, conceptId: concept.concept_id, kind: "alias" }); }
  const unique = [...new Set(candidates)].sort();
  const matches = unique.map((candidate) => {
    const normalized = normalizeLabel(candidate); const hits = labels.filter((label) => normalizeLabel(label.value) === normalized);
    const ids = [...new Set(hits.map((hit) => hit.conceptId))];
    if (ids.length === 1) return { candidate, status: hits.some((hit) => hit.kind === "exact") ? "exact" : "alias", matchedConceptIds: ids };
    if (ids.length > 1) return { candidate, status: "ambiguous", matchedConceptIds: ids };
    return { candidate, status: "missing", matchedConceptIds: [] };
  });
  return { manifestId: "SECURIUM_CPPG_FOUNDATION_ONTOLOGY_DRY_RUN_V1", courseId: "course-cppg", authority: "CURRENT_CANONICAL_ONTOLOGY_READ_ONLY", writes: 0, candidates: matches, summary: { exact: matches.filter((m) => m.status === "exact").length, alias: matches.filter((m) => m.status === "alias").length, missing: matches.filter((m) => m.status === "missing").length, ambiguous: matches.filter((m) => m.status === "ambiguous").length }, previousAuditReference: { missing: 16, ambiguous: 3, reEvaluated: true }, failClosedPolicy: "ambiguous candidates are not mapped and no local canonical concept authority is created", provenance: provenance("ONTOLOGY-DRY-RUN", "ALL") };
}

